('Bindings, arrays, and objects','Use const by default and let for reassignment. JavaScript values are dynamically typed; avoid relying on implicit coercion.','const note = { title: "Cider", tags: ["drink"] };\nconst titles = [note].map(item => item.title);\nconsole.log(titles);','const total = [1, 2, 3].reduce((sum, value) => sum + value, 0);\nconsole.log(total);'),
