('Database access','Use prepared statements with bound values; never concatenate user input into SQL. Configure credentials outside source control.','<?php\n$stmt = $pdo->prepare("SELECT title FROM notes WHERE id = :id");\n$stmt->execute(["id" => $id]);\n$note = $stmt->fetch(PDO::FETCH_ASSOC);','<?php\ntry { $pdo->beginTransaction(); /* validated updates */ $pdo->commit(); }\ncatch (Throwable $e) { if ($pdo->inTransaction()) $pdo->rollBack(); throw $e; }'),
