out=Path(__file__).parent/'manuals';out.mkdir(exist_ok=True)
for key,(name,lang,url,sections) in manuals.items():
 text=f'# {name}: offline working guide\n\nOriginal quick reference for RudyEdit. Search by typing in the popup; use PgUp/PgDn to scroll. This is a practical introduction, not the complete upstream language reference.\n\n'
 for title,desc,a,b in sections:
  text+=f'## {title}\n\n{desc}\n\nExample 1:\n```{lang}\n{a}\n```\n\nExample 2:\n```{lang}\n{b}\n```\n\n'
 text+=f'## Common workflow\n\nSave the file with the proper extension. Press F3 for Development mode, Ctrl+Space for local completion, and F1 for editor commands. Install and explicitly connect a compatible language server for semantic completion and diagnostics. Check tool availability with rudyedit --doctor. The embedded console is a command runner with redirected input/output, rather than a full terminal emulator.\n\nUpstream reference (online): {url}\n'
 (out/f'{key}.md').write_text(text)
for key,(name,url,desc,sections) in related.items():
 text=f'# {name}: offline framework guide\n\n{desc}\n\n'
 for title,code in sections:text+=f'## {title}\n\n```\n{code}\n```\n\n'
 text+=f'## Editor integration\n\nRudyEdit detects the underlying HTML, CSS, React, Vue, or PHP file type. Local completion includes common framework identifiers; configure an appropriate language server for project-specific suggestions. Build and test through your project’s scripts in the embedded console.\n\nUpstream reference (online): {url}\n'
 (out/f'{key}.md').write_text(text)
